import { RotateCcw } from 'lucide-react';
import { useMemo, useState } from 'react';
import type { DeviceConfig, ResourceConfig } from '../../config/schema';
import { resolveAssetUrl } from '../../config/loadConfig';
import { detectModelKind } from '../../shared/modelFormat';
import { hasWebGLSupport } from '../../shared/webgl';
import { DeviceScene, type DeviceSceneComponent } from './DeviceScene';
import './device.css';

export function createModelResourceDevice(resource: ResourceConfig): DeviceConfig {
  if (resource.kind !== 'model') throw new Error('仅模型资源可进入三维查看器');
  return {
    id: `archive-${resource.id}`,
    name: resource.title,
    summary: resource.description,
    poster: resource.poster ?? '',
    source: { kind: detectModelKind(resource.url), url: resource.url },
    camera: { position: [7, 6, 10], target: [0, 0, 0], minDistance: 3, maxDistance: 60 },
    parts: [],
    resourceIds: [],
  };
}

export function ModelResourceViewer({
  resource,
  supportsWebGL = hasWebGLSupport,
  SceneComponent = DeviceScene,
}: {
  resource: ResourceConfig;
  supportsWebGL?: () => boolean;
  SceneComponent?: DeviceSceneComponent;
}) {
  const [resetToken, setResetToken] = useState(0);
  const [webglAvailable] = useState(() => supportsWebGL());
  const device = useMemo(() => createModelResourceDevice(resource), [resource]);
  const sceneState = useMemo(() => ({
    selectedPartId: null,
    isolatedPartId: null,
    hiddenPartIds: [] as string[],
    explode: 0,
    view: 'three-quarter' as const,
    rotate: false,
    reset: resetToken,
    detailsOpen: false,
  }), [resetToken]);
  if (!webglAvailable) return <div className="webgl-fallback model-fallback">{resource.poster && <img src={resolveAssetUrl(resource.poster)} alt={`${resource.title}静态预览`} />}<strong>三维模型资料</strong><p>当前设备不支持 WebGL，请更换浏览器或下载模型查看。</p></div>;
  return (
    <div className="model-resource-viewer">
      <SceneComponent device={device} state={sceneState} onPartSelect={() => undefined} />
      <button type="button" aria-label="复位模型视角" onClick={() => setResetToken(value => value + 1)}><RotateCcw /></button>
    </div>
  );
}

export default ModelResourceViewer;
