import type { ModelSourceKind } from '../config/schema';

const MODEL_EXTENSION_KINDS: ReadonlyArray<{ extension: string; kind: ModelSourceKind }> = [
  { extension: '.fbx', kind: 'fbx' },
  { extension: '.obj', kind: 'obj' },
  { extension: '.stl', kind: 'stl' },
];

/**
 * Infers the model source kind from a file URL. Unknown or glTF-family
 * extensions (`.glb`, `.gltf`) fall back to the `gltf` kind so the existing
 * glTF pipeline keeps working for URLs without an explicit format marker.
 */
export function detectModelKind(url: string): ModelSourceKind {
  const clean = url.replace(/[?#].*$/u, '').trim().toLowerCase();
  for (const entry of MODEL_EXTENSION_KINDS) {
    if (clean.endsWith(entry.extension)) return entry.kind;
  }
  return 'gltf';
}

/** Accepted local file extension per model source kind. */
export const MODEL_KIND_EXTENSIONS: Readonly<Record<ModelSourceKind, string>> = {
  gltf: '.glb',
  fbx: '.fbx',
  obj: '.obj',
  stl: '.stl',
};
